/**
 * The KTBL actions with cost data: one per action and machine variant (FQN such as
 * PLOWING__RP7_1000), with the reference's operation category, crop applicability and its German
 * and English article texts (data/ktbl/actions.json, generated by scripts/generate-ktbl-data.py).
 * Loaded once on first use.
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import type { KtblAction, KtblText, OperationType } from '@agmeo/contracts';

type RawAction = { fqn: string; category: string; appliesTo: string; group: KtblText; label: KtblText };

/**
 * Operation categories of the reference (`subCategoryEnum`) onto the rewrite's operation types.
 * Post-harvest work (drying, storing, transport to the buyer) counts as harvest; maintenance
 * (grassland rolling and harrowing, reseeding, mulching, cleaning) as other.
 */
const OPERATION_TYPE: Record<string, OperationType> = {
  TILLAGE: 'tillage',
  PLANTING: 'sowing',
  FERTILIZING: 'fertilization',
  PROTECTION: 'crop_protection',
  IRRIGATION: 'irrigation',
  HARVESTING: 'harvest',
  POSTHARVEST: 'harvest',
  MONITORING: 'inspection',
  MAINTENANCE: 'other',
  MISCELLANEOUS: 'other',
  OTHERS: 'other',
};

const dataFile = fileURLToPath(new URL('../../../data/ktbl/actions.json', import.meta.url));

let actions: KtblAction[] | null = null;
let byFqn: Map<string, KtblAction> | null = null;

export function ktblActions(): KtblAction[] {
  actions ??= (JSON.parse(readFileSync(dataFile, 'utf-8')) as RawAction[])
    .map((a) => ({
      fqn: a.fqn,
      operationType: OPERATION_TYPE[a.category] ?? 'other',
      category: a.category,
      group: a.group,
      label: a.label,
      appliesTo: a.appliesTo,
    }))
    .sort((a, b) => a.group.de.localeCompare(b.group.de, 'de') || a.label.de.localeCompare(b.label.de, 'de', { numeric: true }));
  return actions;
}

export function ktblAction(fqn: string): KtblAction | undefined {
  byFqn ??= new Map(ktblActions().map((a) => [a.fqn, a]));
  return byFqn.get(fqn);
}

const normalize = (s: string) =>
  s.toLowerCase().replace(/[\s\-_./,()]/g, '').replace(/ä/g, 'a').replace(/ö/g, 'o').replace(/ü/g, 'u').replace(/ß/g, 'ss');

/** Actions of an operation type, offered for crops with these `appliesTo` values, matching every word of `q`. */
export function searchKtblActions(opts: { operationType?: OperationType; appliesTo?: Set<string>; q?: string }): KtblAction[] {
  const words = (opts.q ?? '').split(/\s+/).map(normalize).filter(Boolean);
  return ktblActions().filter(
    (a) =>
      (!opts.operationType || a.operationType === opts.operationType) &&
      (!opts.appliesTo || opts.appliesTo.has(a.appliesTo)) &&
      words.every((w) => normalize(`${a.group.de} ${a.label.de} ${a.group.en} ${a.label.en} ${a.fqn}`).includes(w)),
  );
}
